INSERT INTO "components" VALUES('pic16f887','microcontroladores','PIC16F887-I/P','PIC','chip',2,1,'{"clock": 20, "flash": "8.192 palavras × 14 bits (14 KiB)", "ram": 368, "adc": "10 bits · 14 canais", "voltage": "2–5,5 V", "cpu": "PIC · 8 bits", "logic": "Conforme VDD (2–5,5 V)", "programmer": "PICkit 3 · ICSP", "status": "Estoque · quantidade estimada", "origin": "Inventario_Componentes_Eletronicos_Obsidian.md · 07/05/2026", "external": "Não", "temperature": "−40 a +85 °C (sufixo I)", "serial": "EUSART · SPI · I2C (MSSP compartilhado)", "package": "PDIP-40", "gpio": "35 (RE3 somente entrada)", "eeprom": "256 B", "pwm": "ECCP + CCP", "timers": "2 × 8 bits + 1 × 16 bits", "dac": "Não", "oscillator": "Interno até 8 MHz; externo até 20 MHz", "use": "Controle geral, muitos sensores, teclado e display paralelo.", "notes": "RE3/MCLR é somente entrada. Clock máximo depende da tensão. Pinos analógicos precisam de configuração para uso digital.", "datasheet": "pic16f887.pdf", "pinout": "pic16f887.png", "pinout_source": "pic16f887.pdf"}');
