INSERT INTO "components" VALUES('h7r3','microcontroladores','WeAct H7R3','STM32','placa',1,0,'{"clock": 600, "flash": "64 KiB de boot Flash", "ram": 634880, "adc": "2 ADCs · 12 bits", "voltage": "3,3 V", "cpu": "Cortex-M7 · 32 bits · FPU dupla precisão · DSP · cache", "logic": "3,3 V", "package": "STM32H7R3Z8J6 · UFBGA-144", "gpio": "Conforme conectores no esquema da placa", "eeprom": "Sem EEPROM", "pwm": "Timers avançados e gerais", "timers": "16 × 16 bits + 4 × 32 bits + 2 watchdogs + SysTick (família)", "dac": "Não", "serial": "USART/UART · SPI/I2S · I2C · USB HS/FS · FDCAN · Ethernet", "oscillator": "Núcleo até 600 MHz via PLL", "external": "8 MiB Flash na placa (WeAct)", "programmer": "SWD com ferramentas atualizadas para H7RS; verificar suporte do ST-Link V2", "status": "Adquirida recentemente", "origin": "Modelo informado pelo usuário; documentação oficial WeAct H7R3Zx", "use": "Processamento intenso e aplicações com código em memória externa.", "notes": "64 KiB internos são boot Flash; não comparar diretamente com 512 KiB internos da G474. Ethernet exige circuito físico de interface (PHY). Recursos do chip não garantem conectores na placa.", "datasheet": "stm32h7r3.pdf", "pinout": "h7-pinout.png", "schematic": "h7-schematic.pdf", "temperature": "−40 a +85 °C (sufixo 6)", "special": "CORDIC · 2 controladores DMA", "pinout_source": "h7-pinout.pdf"}');
INSERT INTO "glossary" VALUES('MCU','Microcontroller Unit · unidade microcontroladora','Chip que reúne processador, memória e periféricos.','Executa o firmware e controla entradas e saídas. Uma placa adiciona alimentação, conectores e outros circuitos ao MCU.','A BlackPill é a placa; STM32F411CEU6 é o MCU.');
INSERT INTO "glossary" VALUES('CPU','Central Processing Unit · unidade central de processamento','Núcleo que executa as instruções.','Clock e arquitetura influenciam desempenho. Frequências iguais não implicam a mesma quantidade de trabalho por segundo.','PIC clássico geralmente executa uma instrução em quatro ciclos de clock; Cortex-M tem outra arquitetura.');
INSERT INTO "glossary" VALUES('Clock','Sinal de sincronização','Ritmo de operação do circuito.','O cristal da placa pode ter frequência diferente da CPU: o PLL multiplica ou divide o sinal. Respeite a relação entre tensão e frequência do datasheet.','A BlackPill usa cristal de 25 MHz, admite CPU de 100 MHz e opera em 96 MHz no TCC.');
INSERT INTO "glossary" VALUES('Flash','Memória não volátil regravável','Guarda o programa mesmo sem energia.','É apagada em blocos e tem limite de ciclos de escrita. Flash externa não é automaticamente equivalente à memória interna para executar código.','H7R3: 64 KiB internos para boot e 8 MiB externos na placa WeAct.');
INSERT INTO "glossary" VALUES('SRAM','Static Random-Access Memory · memória estática de acesso aleatório','Memória de trabalho; perde os dados ao desligar.','Armazena variáveis, pilha e buffers. Bancos de SRAM podem ter acessos diferentes para CPU e DMA.','G474: 96 KiB de SRAM mais 32 KiB de CCM; F411: 128 KiB.');
INSERT INTO "glossary" VALUES('EEPROM','Electrically Erasable Programmable Read-Only Memory','Memória não volátil para pequenos dados.','Permite gravar configurações e contadores; observe resistência de escrita e tempo de gravação. Emular EEPROM em Flash exige gerenciar apagamento e desgaste.','PIC16F887 tem 256 bytes; PIC12F1501 oferece HEF no lugar da EEPROM clássica.');
INSERT INTO "glossary" VALUES('ADC','Analog-to-Digital Converter · conversor analógico-digital','Transforma uma tensão em um número.','Resolução indica quantos códigos existem, não a precisão real. Referência, ruído, impedância da fonte e tempo de aquisição afetam a leitura. Canais multiplexados não significam conversão simultânea.','Um ADC de 12 bits oferece 4096 códigos. O ADS1256 do TCC é externo, não o ADC de 12 bits do F411.');
INSERT INTO "glossary" VALUES('DAC','Digital-to-Analog Converter · conversor digital-analógico','Transforma um número em uma tensão analógica.','Confira resolução, faixa de saída, buffer e se o canal chega a um pino externo. PWM filtrado pode aproximar uma saída analógica, mas não é um DAC nativo.','PIC12F1501 tem DAC de 5 bits. F411 não possui DAC.');
INSERT INTO "glossary" VALUES('GPIO','General-Purpose Input/Output · entrada/saída de uso geral','Pino configurável para ler ou produzir sinais digitais.','Pinos podem compartilhar funções e nem todos aceitam saída. Contagem do chip, pinos expostos na placa e pinos livres no projeto são coisas diferentes.','Nos PICs de oito pinos, GP3/RA3 é somente entrada.');
INSERT INTO "glossary" VALUES('PWM','Pulse-Width Modulation · modulação por largura de pulso','Controla a proporção de tempo em nível alto.','Duty cycle é o tempo ligado dividido pelo período. Frequência e resolução dependem do clock e do timer. Para motores ou cargas, use estágio de potência adequado.','PIC12F675 não tem PWM por hardware; PIC12F683 tem um CCP.');
INSERT INTO "glossary" VALUES('UART','Universal Asynchronous Receiver/Transmitter','Comunicação serial assíncrona por transmissão e recepção.','Dois dispositivos precisam concordar em velocidade e formato. Cruze TX com RX e compartilhe GND. Nível lógico não é o mesmo que RS-232.','CH343P conecta a USB do computador à UART de uma placa.');
INSERT INTO "glossary" VALUES('USART','Universal Synchronous/Asynchronous Receiver/Transmitter','Interface serial que também pode operar sincronamente.','No modo assíncrono funciona como uma UART; a disponibilidade de sinais depende do chip e da configuração.','STM32F411 possui interfaces USART.');
INSERT INTO "glossary" VALUES('SPI','Serial Peripheral Interface · interface periférica serial','Barramento síncrono com clock e seleção do dispositivo.','SCK sincroniza os bits; MOSI e MISO transportam dados; CS seleciona o periférico. Polaridade e fase devem coincidir nos dois lados.','No TCC, SPI2 da BlackPill atende ao ADS1256.');
INSERT INTO "glossary" VALUES('I2C','Inter-Integrated Circuit · barramento entre circuitos','Comunicação por duas linhas: SDA e SCL.','Usa endereços e saídas de dreno aberto com resistores pull-up. Verifique tensão dos pull-ups, capacitância e endereços repetidos.','Sensores e displays podem compartilhar o barramento, desde que os endereços sejam compatíveis.');
INSERT INTO "glossary" VALUES('FPU','Floating-Point Unit · unidade de ponto flutuante','Hardware que acelera contas com números fracionários.','A precisão suportada depende do núcleo. O compilador precisa configurar corretamente a geração das instruções.','F411 e G474 possuem FPU de precisão simples; BluePill Cortex-M3 não.');
INSERT INTO "glossary" VALUES('DSP','Digital Signal Processing · processamento digital de sinais','Operações para filtrar e analisar sinais.','Instruções DSP aceleram tarefas como multiplicar e acumular. Não substituem planejamento da amostragem, memória e fluxo de dados.','Filtros de sinais adquiridos pelo TCC podem aproveitar instruções do Cortex-M4.');
INSERT INTO "glossary" VALUES('DMA','Direct Memory Access · acesso direto à memória','Transfere dados sem a CPU copiar cada item.','Um controlador move dados entre periféricos e memória. Confira bancos acessíveis, largura das transferências e coerência de cache.','É útil para receber amostras SPI em buffers.');
INSERT INTO "glossary" VALUES('SWD','Serial Wire Debug · depuração serial','Interface de gravação e depuração dos Arm.','Usa SWDIO e SWCLK, além da referência de terra e tensão; reset pode ajudar. O programa do gravador precisa reconhecer o chip.','ST-Link V2 atende às BluePill e BlackPill; H7RS requer verificar suporte atualizado.');
INSERT INTO "glossary" VALUES('ICSP','In-Circuit Serial Programming · programação no circuito','Gravação sem remover o microcontrolador da montagem.','No PIC usa MCLR/VPP, VDD, VSS, dados e clock. O conector AVR também chamado ICSP tem sinais e protocolo diferentes.','PICkit 3 para PICs; não tratar ICSP do Arduino como compatível com PICkit.');
INSERT INTO "glossary" VALUES('DFU','Device Firmware Upgrade · atualização de firmware','Protocolo USB para carregar firmware.','Depende de bootloader e do modo de inicialização. Uma porta USB presente na placa não garante DFU em qualquer configuração.','A BlackPill F411 pode usar o bootloader de fábrica por USB.');
INSERT INTO "glossary" VALUES('USB','Universal Serial Bus · barramento serial universal','Interface de comunicação e alimentação.','A função pode ser dispositivo ou host. FS significa Full Speed (12 Mbit/s), HS High Speed (480 Mbit/s). O chip e a placa precisam oferecer o circuito necessário.','No Uno clássico a USB passa por uma ponte; no F411 o MCU possui USB nativa.');
INSERT INTO "glossary" VALUES('CAN','Controller Area Network · rede de controladores','Barramento robusto para comunicação entre dispositivos.','O controlador do MCU normalmente precisa de um transceptor externo e terminação adequada. Recursos compartilhados podem limitar operação simultânea.','F103 possui CAN 2.0B; F411 não tem CAN.');
INSERT INTO "glossary" VALUES('FDCAN','Flexible Data-rate CAN · CAN com taxa de dados flexível','Controlador CAN com suporte a quadros CAN FD.','Permite maior carga útil e taxa na fase de dados. Não dispensa transceptor compatível. Quantidade e pinos variam por modelo.','G474 e H7R3 têm FDCAN; a placa não necessariamente inclui transceptor.');
INSERT INTO "glossary" VALUES('HRTIM','High-Resolution Timer · temporizador de alta resolução','Temporizador para controle preciso de pulsos.','Útil em conversores de potência com saídas complementares, sincronização e proteção. A resolução fina não equivale ao período mínimo completo.','É um diferencial do G474 para controle de potência.');
INSERT INTO "glossary" VALUES('CORDIC','Coordinate Rotation Digital Computer','Acelerador de funções trigonométricas.','Calcula operações como seno e cosseno por um algoritmo iterativo em hardware. Observe formato numérico, escala e precisão configurada.','Disponível no G474 para controle vetorial e cálculo de sinais.');
INSERT INTO "glossary" VALUES('FMAC','Filter Math Accelerator · acelerador matemático de filtros','Hardware dedicado a cálculos de filtragem.','Ajuda a executar filtros digitais. Coeficientes, escalonamento e saturação precisam ser configurados.','G474 possui FMAC; F411 utiliza CPU e instruções DSP.');
INSERT INTO "glossary" VALUES('HEF','High-Endurance Flash · Flash de alta resistência','Área Flash destinada a dados gravados com frequência.','Não é EEPROM convencional; respeite sequência de apagamento e escrita e os limites do fabricante.','PIC12F1501 oferece 128 bytes de HEF.');
INSERT INTO "glossary" VALUES('CLC','Configurable Logic Cell · célula lógica configurável','Combina sinais por lógica em hardware.','Pode implementar funções lógicas sem instruções contínuas da CPU. As fontes e saídas disponíveis são limitadas pelo dispositivo.','PIC12F1501 oferece duas CLC.');
INSERT INTO "glossary" VALUES('NCO','Numerically Controlled Oscillator · oscilador controlado numericamente','Gera pulsos por acumulação numérica.','Um acumulador recebe incrementos a cada clock. O valor do incremento determina a frequência média de saída.','PIC12F1501 inclui NCO para geração de sinais.');
INSERT INTO "glossary" VALUES('CWG','Complementary Waveform Generator','Gerador de formas de onda complementares.','Produz sinais relacionados, com controles como tempo morto, conforme o chip. Não substitui o driver de potência.','PIC12F1501 possui CWG.');
INSERT INTO "glossary" VALUES('VDD','Tensão positiva de alimentação','Alimentação do microcontrolador.','A faixa de alimentação do chip é diferente da entrada VIN da placa. Consulte também limites por frequência e alimentação analógica VDDA.','USB de 5 V pode alimentar o regulador de uma placa STM32, mas seus GPIO operam em 3,3 V.');
INSERT INTO "glossary" VALUES('VSS','Referência negativa de alimentação','Referência de terra do chip.','Normalmente ligada ao GND do circuito. O retorno e o desacoplamento influenciam a integridade dos sinais.','PIC usa VSS no datasheet; placas costumam rotular GND.');
INSERT INTO "glossary" VALUES('GND','Ground · terra de referência','Referência comum de tensão do circuito.','Dispositivos ligados por sinais elétricos precisam compartilhar uma referência adequada. Terra de circuito não implica terra de proteção.','Una GND do adaptador serial ao GND da placa.');
INSERT INTO "glossary" VALUES('MCLR','Master Clear · reinicialização principal','Entrada de reset dos PICs.','Pode compartilhar a função VPP de programação. Dependendo dos bits de configuração pode virar entrada digital, nunca assuma uma saída.','Pino 4 dos PICs de oito pinos compartilha MCLR e VPP.');
INSERT INTO "glossary" VALUES('PLL','Phase-Locked Loop · malha de captura de fase','Circuito que gera clocks derivados de uma referência.','Multiplicadores e divisores devem respeitar as faixas internas. Periféricos como USB exigem clocks específicos.','O TCC configura CPU do F411 em 96 MHz e USB em 48 MHz.');
INSERT INTO "glossary" VALUES('CCP','Capture/Compare/PWM','Periférico de captura, comparação e PWM.','Captura mede o instante de um evento; comparação dispara ao atingir um valor; PWM gera pulsos periódicos.','PIC12F683 tem um CCP; PIC16F887 tem CCP e ECCP.');
INSERT INTO "glossary" VALUES('Timer','Temporizador/contador','Conta ciclos ou eventos externos.','Um prescaler divide o clock de entrada. O estouro ou comparação pode gerar interrupções. Watchdog é um temporizador de recuperação, não uma saída PWM.','PIC12F675 tem Timer0 de 8 bits e Timer1 de 16 bits.');
INSERT INTO "glossary" VALUES('GPIO 5 V tolerant','Entrada tolerante a 5 V','Alguns pinos aceitam 5 V sob condições específicas.','Tolerância não se aplica automaticamente em modo analógico nem com o chip desligado. Não significa que o pino produz 5 V na saída.','Consulte a coluna de tipo de I/O no datasheet STM32 antes de conectar módulos de 5 V.');
INSERT INTO "glossary" VALUES('KiB','Kibibyte · 1024 bytes','Unidade binária de capacidade de memória.','Um KiB contém 1024 bytes; um MiB contém 1048576 bytes. Fabricantes frequentemente escrevem KB para capacidades binárias.','512 KiB = 524288 bytes. Palavras de 14 bits dos PICs precisam ser descritas separadamente.');
INSERT INTO "glossary" VALUES('Pinout','Mapa de pinagem','Desenho que relaciona pinos e funções.','Confira vista superior ou inferior, referência do pino 1, encapsulamento e revisão da placa. Funções alternativas no mesmo pino não operam todas simultaneamente.','O mapa da G474 Long é diferente do layout compacto mesmo com o mesmo MCU.');
INSERT INTO "glossary" VALUES('Datasheet','Folha de dados do fabricante','Documento de especificações do componente.','Reúne pinagem, limites elétricos e temporizações. O manual de referência explica registros; errata registra limitações conhecidas.','Use o datasheet local para limites completos; a tabela do acervo resume critérios de escolha.');
INSERT INTO "glossary" VALUES('OPAMP','Operational Amplifier · amplificador operacional','Amplifica a diferença entre duas entradas.','Modelos integrados podem conectar sinais internamente. Faixa de entrada, ganho, banda e pinos expostos limitam o uso.','G474 inclui amplificadores operacionais para aplicações analógicas.');
INSERT INTO "glossary" VALUES('CCM','Core-Coupled Memory · memória acoplada ao núcleo','Banco de memória com acesso dedicado ao núcleo.','Não assuma que qualquer controlador DMA pode acessar esse banco. Verifique o mapa de barramentos.','32 KiB dos 128 KiB de SRAM do G474 são CCM.');
INSERT INTO "glossary" VALUES('Bootloader','Carregador de inicialização','Programa que inicia ou atualiza a aplicação.','Pode residir em ROM de fábrica ou ocupar parte da Flash do usuário. O endereço de início da aplicação deve corresponder à configuração.','No firmware do TCC com bootloader WeAct, a aplicação começa em 0x08004000.');
INSERT INTO "glossary" VALUES('MHz','Megahertz','Um milhão de ciclos por segundo.','É unidade de frequência, não de instruções executadas por segundo. Considere arquitetura, memória e periféricos.','100 MHz é o limite da CPU do F411; o cristal de 25 MHz é outra referência.');
INSERT INTO "glossary" VALUES('VREF','Reference Voltage · tensão de referência','Referência que define a escala de um conversor.','Ruído e erro da referência afetam a medição. Não confunda tensão máxima de alimentação com escala do ADC.','Escolha a referência antes de converter códigos ADC em volts.');
INSERT INTO "glossary" VALUES('VIL','Voltage Input Low','Maior tensão garantida como nível lógico baixo.','Leia a coluna de condições. Uma entrada entre VIL máximo e VIH mínimo não tem estado lógico garantido.','Importante ao interligar dispositivos de 3,3 V e 5 V.');
INSERT INTO "glossary" VALUES('VIH','Voltage Input High','Menor tensão garantida como nível lógico alto.','Depende do tipo de entrada e alimentação. Compatibilidade exige que a saída do transmissor satisfaça este limite.','Uma saída de 3,3 V nem sempre satisfaz uma entrada de 5 V.');
INSERT INTO "glossary" VALUES('VOL','Voltage Output Low','Tensão de saída quando o pino produz nível baixo.','O valor depende da corrente absorvida e da alimentação. A saída não é um curto ideal ao terra.','Confira a corrente de teste na tabela elétrica.');
INSERT INTO "glossary" VALUES('VOH','Voltage Output High','Tensão de saída quando o pino produz nível alto.','A corrente fornecida pode reduzir a tensão. Não dimensione cargas só pelo limite máximo absoluto do pino.','VOH mínimo do transmissor precisa superar VIH mínimo do receptor.');
INSERT INTO "glossary" VALUES('IDD','Supply Current','Corrente consumida pela alimentação do circuito.','O consumo varia com clock, temperatura, tensão e periféricos ativos. Valores típicos não são garantias de máximo.','Compare chips sob condições equivalentes para projetos a bateria.');
INSERT INTO "glossary" VALUES('Absolute Maximum Ratings','Limites máximos absolutos','Limites além dos quais pode haver dano.','Não são condições normais de operação. Use a faixa operacional recomendada para projetar.','A corrente máxima absoluta de um GPIO não é a corrente recomendada de trabalho.');
INSERT INTO "glossary" VALUES('Typical','Valor típico','Valor representativo em condições de teste.','Não é limite garantido para todas as unidades. Para dimensionar margens use mínimo/máximo quando fornecidos.','Consumo típico muda com tensão, clock e temperatura.');
INSERT INTO "glossary" VALUES('Min','Minimum · mínimo','Menor valor especificado nas condições da tabela.','Leia unidades e condições: um mínimo pode indicar um requisito que seu circuito precisa atender.','VIH mínimo define a tensão necessária para entrada alta.');
INSERT INTO "glossary" VALUES('Max','Maximum · máximo','Maior valor especificado nas condições da tabela.','Não confunda limite operacional garantido com limite absoluto de dano.','Clock máximo depende da alimentação em vários PICs.');
INSERT INTO "glossary" VALUES('LSB','Least Significant Bit · bit menos significativo','Menor passo do código digital.','No ADC ideal, o passo é aproximadamente a faixa de referência dividida pelo número de códigos. Precisão real inclui outros erros.','12 bits oferecem 4096 códigos, mas não garantem 12 bits livres de ruído.');
INSERT INTO "glossary" VALUES('INL','Integral Nonlinearity · não linearidade integral','Desvio da transferência real em relação à reta ideal.','Geralmente expresso em LSB; afeta a exatidão ao longo da faixa. Consulte o método usado pelo fabricante.','É uma especificação importante para comparar ADCs além da resolução.');
INSERT INTO "glossary" VALUES('DNL','Differential Nonlinearity · não linearidade diferencial','Variação do tamanho de cada passo de conversão.','Relaciona-se a códigos ausentes e monotonicidade. Resolução nominal não descreve essa variação.','Confira a tabela ADC do componente quando a precisão importa.');
INSERT INTO "glossary" VALUES('ENOB','Effective Number of Bits · número efetivo de bits','Resolução efetiva considerando ruído e distorção.','É obtido sob condições de ensaio, frequentemente por relação sinal-ruído e distorção. Não equivale simplesmente ao número de bits do registrador.','Um ADC nominal de 12 bits pode ter ENOB menor.');
INSERT INTO "glossary" VALUES('SNR','Signal-to-Noise Ratio · relação sinal-ruído','Relação entre potência do sinal e do ruído.','É frequentemente expressa em decibéis. Banda, amplitude e configuração de teste precisam acompanhar o número.','Útil na análise da cadeia de aquisição do TCC.');
INSERT INTO "glossary" VALUES('SPS','Samples Per Second · amostras por segundo','Taxa de produção de amostras.','Taxa total do conversor não é necessariamente taxa por canal. Troca de canal e filtros também consomem tempo.','No sistema ADS1256, não divida a taxa nominal sem considerar a sequência de aquisição.');
INSERT INTO "glossary" VALUES('MSPS','Million Samples Per Second','Milhões de amostras por segundo.','É taxa de conversão, não frequência de CPU. Banda útil e precisão dependem da configuração.','ADCs rápidos do G474 são úteis para controle, desde que a entrada estabilize.');
INSERT INTO "glossary" VALUES('HSE','High-Speed External oscillator','Fonte externa de clock de alta frequência.','Pode usar cristal ou sinal externo conforme configuração. Capacitores e modo de oscilador precisam corresponder ao circuito.','BlackPill: cristal HSE de 25 MHz.');
INSERT INTO "glossary" VALUES('HSI','High-Speed Internal oscillator','Oscilador interno de alta frequência.','Dispensa cristal externo, mas precisão varia conforme o dispositivo e condições. Calibração pode ser relevante.','STM32G474 inclui HSI de 16 MHz.');
INSERT INTO "glossary" VALUES('LSE','Low-Speed External oscillator','Fonte externa de baixa frequência.','Normalmente um cristal de 32,768 kHz para relógio de tempo real. Confira se a placa tem o cristal instalado.','A existência do periférico RTC não confirma cristal LSE na placa.');
INSERT INTO "glossary" VALUES('RTC','Real-Time Clock · relógio de tempo real','Periférico que mantém a contagem de tempo.','Pode permanecer ativo com alimentação de backup. Precisão depende da fonte de clock e calibração.','VBAT pode alimentar o domínio de backup de STM32.');
INSERT INTO "glossary" VALUES('VBAT','Backup Battery supply','Alimentação do domínio de backup.','Normalmente usada para manter RTC e registros de backup. Não é a alimentação geral da placa.','Confira VBAT no pinout da BlackPill antes de ligar uma bateria.');
INSERT INTO "glossary" VALUES('NRST','Reset ativo em nível baixo','Pino que reinicia o microcontrolador.','O prefixo N indica ativação em nível baixo. Reset não é desligamento e não apaga a Flash.','ST-Link pode usar NRST para conectar sob reset.');
INSERT INTO "glossary" VALUES('BOOT0','Boot selection pin','Sinal que participa da seleção de inicialização.','A seleção também pode depender de bits de opção. Consulte o procedimento do modelo antes de entrar no bootloader.','Na BlackPill, BOOT0 e RESET permitem entrar no bootloader de fábrica.');
INSERT INTO "glossary" VALUES('MOSI','Master Out Slave In','Linha SPI do controlador para o periférico.','Também chamada COPI, Controller Out Peripheral In. Conecte os sinais conforme a direção definida no dispositivo.','PB15 é usado como saída SPI2 para ADS1256 no TCC.');
INSERT INTO "glossary" VALUES('MISO','Master In Slave Out','Linha SPI do periférico para o controlador.','Também chamada CIPO, Controller In Peripheral Out. Dispositivos não selecionados devem liberar a linha quando compartilhada.','PB14 recebe dados do ADS1256 via SPI2 no TCC.');
INSERT INTO "glossary" VALUES('SCK','Serial Clock','Clock que sincroniza os bits da interface serial.','Em SPI, frequência, polaridade e fase precisam corresponder às exigências do periférico.','PB13 fornece SCK do SPI2 na montagem do TCC.');
INSERT INTO "glossary" VALUES('SDA','Serial Data','Linha de dados do barramento I2C.','É bidirecional e normalmente precisa de pull-up. A tensão do pull-up define o nível alto.','No Uno, A4 corresponde a SDA.');
INSERT INTO "glossary" VALUES('SCL','Serial Clock Line','Linha de clock do barramento I2C.','Normalmente usa pull-up. Resistência e capacitância afetam o tempo de subida e a velocidade possível.','No Uno, A5 corresponde a SCL.');
INSERT INTO "glossary" VALUES('TX','Transmit · transmissão','Sinal de saída de dados seriais.','Para UART entre dois dispositivos, normalmente liga ao RX do outro. Confirme a perspectiva da rotulagem do adaptador.','TX do CH343P vai ao RX da placa.');
INSERT INTO "glossary" VALUES('RX','Receive · recepção','Sinal de entrada de dados seriais.','Recebe o TX do outro dispositivo. Compatibilidade de tensão e referência de terra são necessárias.','RX do CH343P recebe o TX da placa.');
INSERT INTO "glossary" VALUES('CS','Chip Select · seleção do chip','Sinal que seleciona o dispositivo SPI.','Frequentemente ativo em nível baixo. Um periférico pode exigir tempos mínimos entre seleção, clock e desativação.','PA4 é o CS previsto da Flash externa da BlackPill.');
INSERT INTO "glossary" VALUES('Pull-up','Resistor para a alimentação positiva','Mantém uma linha em nível alto quando ninguém a aciona.','Evita entrada flutuante e permite barramentos de dreno aberto. O valor depende de corrente e velocidade desejadas.','SDA e SCL em I2C precisam de pull-ups apropriados.');
INSERT INTO "glossary" VALUES('Open Drain','Saída de dreno aberto','Saída que puxa para baixo ou fica em alta impedância.','Precisa de pull-up para obter nível alto. Permite vários participantes compartilharem o sinal.','I2C utiliza essa forma de saída.');
INSERT INTO "glossary" VALUES('Watchdog','Temporizador de supervisão','Reinicia ou sinaliza se o software deixa de responder.','Precisa ser atendido no prazo configurado. Não resolve toda falha e não deve ser alimentado indiscriminadamente.','PICs e STM32 incluem mecanismos watchdog.');
INSERT INTO "glossary" VALUES('Interrupt','Interrupção','Evento que desvia a execução para uma rotina de atendimento.','Prioridade e tempo de atendimento afetam a resposta. Evite operações demoradas nas rotinas críticas.','Um sinal de amostra pronta pode disparar uma interrupção.');
INSERT INTO "glossary" VALUES('Fuses','Bits de configuração','Configurações persistentes do microcontrolador.','Controlam clock, reset, proteção e outros comportamentos. Em STM32 funções parecidas usam option bytes.','Uma configuração de clock incorreta pode impedir a execução esperada no PIC.');
INSERT INTO "glossary" VALUES('PDIP','Plastic Dual In-line Package','Encapsulamento plástico com duas fileiras de terminais.','O número indica quantidade total de pinos. Identifique entalhe e pino 1 antes de ligar.','PIC16F887-I/P tem PDIP de 40 pinos.');
INSERT INTO "glossary" VALUES('LQFP','Low-profile Quad Flat Package','Encapsulamento fino com terminais em quatro lados.','O número de pinos é do chip, não de sinais digitais livres. Alimentação e funções reservadas ocupam terminais.','STM32F103C8T6 usa LQFP de 48 pinos.');
INSERT INTO "glossary" VALUES('UFQFPN','Ultra-thin Fine-pitch Quad Flat Package No-lead','Encapsulamento fino com contatos sem pernas expostas.','A pinagem e pad central precisam seguir o desenho do fabricante. Não é intercambiável fisicamente com LQFP.','STM32G474CEU6 e STM32F411CEU6 usam UFQFPN de 48 pinos.');
INSERT INTO "glossary" VALUES('UFBGA','Ultra-thin Fine-pitch Ball Grid Array','Encapsulamento com esferas de contato por baixo.','A numeração é uma matriz de posições. Confira a orientação superior/inferior no desenho do fabricante.','STM32H7R3Z8J6 usa UFBGA de 144 contatos.');
INSERT INTO "glossary" VALUES('PCB','Printed Circuit Board · placa de circuito impresso','Placa que interliga eletricamente os componentes.','O layout físico define quais sinais estão conectados e quais chegam aos conectores.','Um dos seus Nano está soldado em uma PCB.');
INSERT INTO "glossary" VALUES('PHY','Physical Layer · camada física','Circuito que traduz sinais digitais para o meio físico.','Ter um controlador Ethernet no chip não significa ter o PHY, conector e demais componentes na placa.','Consulte o esquema antes de planejar Ethernet com H7R3.');
INSERT INTO "glossary" VALUES('ECCP','Enhanced Capture/Compare/PWM','Versão ampliada do periférico CCP.','Pode oferecer saídas e modos para acionamento de pontes conforme o modelo. Configuração e pinos limitam o uso.','PIC16F887 inclui ECCP.');
INSERT INTO "glossary" VALUES('MSSP','Master Synchronous Serial Port','Periférico de comunicação síncrona dos PICs.','Pode operar como SPI ou I2C. Um único módulo não executa as duas interfaces ao mesmo tempo.','PIC16F887 oferece SPI e I2C pelo MSSP compartilhado.');
INSERT INTO "glossary" VALUES('EUSART','Enhanced USART','Interface serial universal aprimorada.','Acrescenta recursos conforme o modelo, como detecção de baud rate. Consulte o capítulo do periférico.','PIC16F887 possui EUSART para comunicação serial.');
INSERT INTO "tools" VALUES('ch343p','CH343P',1,'Ponte USB–UART: permite comunicação serial com o computador. Não é depurador.','UART de STM32 quando o bootloader do modelo permite. Conferir nível lógico do módulo; ligar TX→RX, RX→TX e GND. Não fornece SWD.');
INSERT INTO "tools" VALUES('stlink','ST-Link V2',1,'Programador e depurador: grava firmware e permite inspecionar execução.','BluePill F103 e BlackPill F411 via SWD. G474 requer software atualizado; conferir suporte H7RS para H7R3 e variante/firmware do gravador.');
INSERT INTO "tools" VALUES('pickit','PICkit 3',1,'Programador e depurador de microcontroladores Microchip. Nome informado como “picokit 3”.','PIC16F887, PIC12F675, PIC12F683 e PIC12F1501 via ICSP, com versão de software que liste o dispositivo. Depuração pode exigir recursos adicionais; não serve como gravador AVR do Arduino.');
