-- Gerado de inventory.sqlite; edite o banco e execute scripts/export.py.
BEGIN TRANSACTION;
CREATE TABLE categories(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE components(id TEXT PRIMARY KEY,category_id TEXT NOT NULL REFERENCES categories(id),name TEXT NOT NULL,family TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('chip','placa')),quantity INTEGER NOT NULL CHECK(quantity>=0),estimated INTEGER NOT NULL CHECK(estimated IN(0,1)),specs TEXT NOT NULL CHECK(json_valid(specs)));
CREATE TABLE glossary(term TEXT PRIMARY KEY,meaning TEXT NOT NULL,short TEXT NOT NULL,detail TEXT NOT NULL,example TEXT NOT NULL);
CREATE TABLE tools(id TEXT PRIMARY KEY,name TEXT NOT NULL,quantity INTEGER NOT NULL,description TEXT NOT NULL,compatibility TEXT NOT NULL);
COMMIT;
PRAGMA user_version=1;
